import{_ as p,a0 as d,w as l,s as t,ao as c,I as i,x as e,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Linux 下使用 sudo 進行賦權 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下使用 sudo 進行賦權 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下使用 sudo 進行賦權 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下使用 sudo 進行賦權 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171205 Using sudo to delegate permissions in Linux","title":"Linux 下使用 sudo 進行賦權","tag":"201801","desc":""},"relativePath":"201801/20171205 Using sudo to delegate permissions in Linux.md","filePath":"[post].md"}'),r={name:"201801/20171205 Using sudo to delegate permissions in Linux.md"};function u(h,s,g,b,k,m){const a=d("Link");return l(),t("div",null,[s[13]||(s[13]=c(`<h1 id="linux-下使用-sudo-進行賦權" tabindex="-1">Linux 下使用 sudo 進行賦權 <a class="header-anchor" href="#linux-下使用-sudo-進行賦權" aria-label="Permalink to “Linux 下使用 sudo 進行賦權”">​</a></h1><blockquote><p>學習怎麼在保護 root 密碼的安全性的同時，為可信用户賦予所管理的網絡功能和特定服務的權限。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/EDU_UnspokenBlockers_1110_A.png?itok=x8A9mqVA" alt=""></p><p>我最近寫了一個簡短的 Bash 程序來將 MP3 文件從一台網絡主機的 USB 盤中拷貝到另一台網絡主機上去。拷貝出來的文件存放在一台志願者組織所屬服務器的特定目錄下，在那裏，這些文件可以被下載和播放。</p><p>我的程序還會做些其他事情，比如為了自動在網頁上根據日期排序，在拷貝文件之前會先對這些文件重命名。在驗證拷貝完成後，還會刪掉 USB 盤中的所有文件。這個小程序還有一些其他選項，比如 <code>-h</code> 會顯示幫助， <code>-t</code> 進入測試模式等等。</p><p>我的程序需要以 root 運行才能發揮作用。然而，這個組織中之後很少的人對管理音頻和計算機系統有興趣的，這使得我不得不找那些半吊子的人來，並培訓他們登錄到用於傳輸的計算機，運行這個小程序。</p><p>倒不是説我不能親自運行這個程序，但由於外出和疾病等等各種原因， 我不是時常在場的。 即使我在場，作為一名 “懶惰的系統管理員”， 我也希望別人能替我把事情給做了。 因此我寫了一些腳本來自動完成這些任務並通過 <code>sudo</code> 來指定某些人來運行這些腳本。 很多 Linux 命令都需要用户以 root 身份來運行。 <code>sudo</code> 能夠保護系統免遭一時糊塗造成的意外損壞以及惡意用户的故意破壞。</p><h3 id="儘可能的使用-sudo" tabindex="-1">儘可能的使用 sudo <a class="header-anchor" href="#儘可能的使用-sudo" aria-label="Permalink to “儘可能的使用 sudo”">​</a></h3><p><code>sudo</code> 是一個很方便的工具，它讓我一個具有 root 權限的管理員可以分配所有或者部分管理性的任務給其他用户， 而且還無需告訴他們 root 密碼， 從而保證主機的高安全性。</p><p>假設，我給了普通用户 <code>ruser</code> 訪問我 Bash 程序 <code>myprog</code> 的權限， 而這個程序的部分功能需要 root 權限。 那麼該用户可以以 <code>ruser</code> 的身份登錄，然後通過以下命令運行 <code>myprog</code>。</p><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myprog</span></span></code></pre></div><p><code>sudo</code> 程序會檢查 <code>/etc/sudoers</code> 文件，並確認 <code>ruser</code> 是否被許可運行 <code>myprog</code>。如被許可，<code>sudo</code> 會要求該用户輸入其密碼——而非 root 密碼。在 <code>ruser</code> 輸入他的密碼之後，該程序就運行了。此外，<code>sudo</code> 也記錄 <code>myprog</code> 該程序運行的日期和時間、完整的命令，以及誰在運行它。這個數據會記錄在 <code>/var/log/security</code> 中。</p><p>我發現在培訓時記錄下每個用 <code>sudo</code> 執行的命令會很有幫助。我可以看到誰執行了哪些命令，他們是否輸對了。</p><p>我委派了權限給自己和另一個人來運行那一個程序；然而，<code>sudo</code> 可以做更多的事情。 它允許系統管理員委派所管理的網絡功能或特定的服務給某個受信的人或某組人。這可以讓你在保護了 root 密碼的安全性的同時，也賦予了那些功能。</p><h3 id="配置-sudoers-文件" tabindex="-1">配置 sudoers 文件 <a class="header-anchor" href="#配置-sudoers-文件" aria-label="Permalink to “配置 sudoers 文件”">​</a></h3><p>作為一名系統管理員，我使用 <code>/etc/sudoers</code> 文件來設置某些用户或某些用户組可以訪問某個命令，或某組命令，或所有命令。 這種靈活性是使用 <code>sudo</code> 進行委派時能兼顧功能與簡易性的關鍵。</p><p>我一開始對 <code>sudoers</code> 文件感到很困惑，因此下面我會拷貝並分解我所使用主機上的完整 <code>sudoers</code> 文件。 希望在分析的過程中不會讓你感到困惑。 我意外地發現， 基於 Red Hat 的發行版中默認的配置文件都會很多註釋以及例子來指導你如何做出修改，這使得修改配置文件變得簡單了很多，也不需要在互聯網上搜索那麼多東西了。</p><p>不要直接用編輯器來修改 <code>sudoers</code> 文件，而應該用 <code>visudo</code> 命令，因為該命令會在你保存並退出編輯器後就立即生效這些變更。 <code>visudo</code> 也可以使用除了 Vi 之外的其他編輯器。</p><p>讓我們首先來分析一下文件中的各種別名。</p><h4 id="主機別名" tabindex="-1">主機別名 <a class="header-anchor" href="#主機別名" aria-label="Permalink to “主機別名”">​</a></h4><p>主機別名這一節用於創建主機分組，授予該組主機可以訪問哪些命令或命令別名。 它的基本思想是，該文件由組織中的所有主機共同維護，然後拷貝到每台主機中的 <code>/etc</code> 中。 其中有些主機， 例如各種服務器， 可以配置成一個組來賦予用户訪問特定命令的權限， 比如可以啓停類似 HTTPD、DNS 以及網絡服務；可以掛載文件系統等等。</p><p>在設置主機別名時也可以用 IP 地址替代主機名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>## Host Aliases</span></span>
<span class="line"><span>## Groups of machines. You may prefer to use hostnames (perhaps using </span></span>
<span class="line"><span>## wildcards for entire domains) or IP addresses instead.</span></span>
<span class="line"><span># Host_Alias     FILESERVERS = fs1, fs2</span></span>
<span class="line"><span># Host_Alias     MAILSERVERS = smtp, smtp2</span></span></code></pre></div><h4 id="用户別名" tabindex="-1">用户別名 <a class="header-anchor" href="#用户別名" aria-label="Permalink to “用户別名”">​</a></h4><p>用户別名允許 root 將用户整理成別名組中，並按組來分配特定的 root 權限。在這部分內容中我加了一行 <code>User_Alias AUDIO = dboth, ruser</code>，定義了一個別名 <code>AUDIO</code> 用來指代了兩個用户。</p><p>正如 <code>sudoers</code> 文件中所闡明的，也可以直接使用 <code>/etc/groups</code> 中定義的組而不用自己設置別名。 如果你定義好的組（假設組名為 <code>audio</code>）已經能滿足要求了， 那麼在後面分配命令時只需要在組名前加上 <code>%</code> 號，像這樣: <code>%audio</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>## User Aliases</span></span>
<span class="line"><span>## These aren&#39;t often necessary, as you can use regular groups</span></span>
<span class="line"><span>## (ie, from files, LDAP, NIS, etc) in this file - just use %groupname </span></span>
<span class="line"><span>## rather than USERALIAS</span></span>
<span class="line"><span># User_Alias ADMINS = jsmith, mikem</span></span>
<span class="line"><span>User_Alias AUDIO = dboth, ruser</span></span></code></pre></div><h4 id="命令別名" tabindex="-1">命令別名 <a class="header-anchor" href="#命令別名" aria-label="Permalink to “命令別名”">​</a></h4><p>再後面是命令別名的部分。這些別名表示的是一系列相關的命令， 比如網絡相關命令，或者 RPM 包管理命令。 這些別名允許系統管理員方便地為一組命令分配權限。</p><p>該部分內容已經設置好了許多別名，這使得分配權限給某類命令變得方便很多。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>## Command Aliases</span></span>
<span class="line"><span>## These are groups of related commands...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Networking</span></span>
<span class="line"><span># Cmnd_Alias NETWORKING = /sbin/route, /sbin/ifconfig, /bin/ping, /sbin/dhclient, /usr/bin/net, /sbin/iptables, /usr/bin/rfcomm, /usr/bin/wvdial, /sbin/iwconfig, /sbin/mii-tool</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Installation and management of software</span></span>
<span class="line"><span># Cmnd_Alias SOFTWARE = /bin/rpm, /usr/bin/up2date, /usr/bin/yum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Services</span></span>
<span class="line"><span># Cmnd_Alias SERVICES = /sbin/service, /sbin/chkconfig</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Updating the locate database</span></span>
<span class="line"><span># Cmnd_Alias LOCATE = /usr/bin/updatedb</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Storage</span></span>
<span class="line"><span># Cmnd_Alias STORAGE = /sbin/fdisk, /sbin/sfdisk, /sbin/parted, /sbin/partprobe, /bin/mount, /bin/umount</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Delegating permissions</span></span>
<span class="line"><span># Cmnd_Alias DELEGATING = /usr/sbin/visudo, /bin/chown, /bin/chmod, /bin/chgrp </span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Processes</span></span>
<span class="line"><span># Cmnd_Alias PROCESSES = /bin/nice, /bin/kill, /usr/bin/kill, /usr/bin/killall</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Drivers</span></span>
<span class="line"><span># Cmnd_Alias DRIVERS = /sbin/modprobe</span></span></code></pre></div><h4 id="環境默認值" tabindex="-1">環境默認值 <a class="header-anchor" href="#環境默認值" aria-label="Permalink to “環境默認值”">​</a></h4><p>下面部分內容設置默認的環境變量。這部分最值得關注的是 <code>!visiblepw</code> 這一行， 它表示當用户環境設置成顯示密碼時禁止 <code>sudo</code> 的運行。 這個安全措施不應該被修改掉。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span># Defaults specification</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># Refuse to run if unable to disable echo on the tty.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>Defaults   !visiblepw</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Defaults    env_reset</span></span>
<span class="line"><span>Defaults    env_keep =  &quot;COLORS DISPLAY HOSTNAME HISTSIZE KDEDIR LS_COLORS&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;MAIL PS1 PS2 QTDIR USERNAME LANG LC_ADDRESS LC_CTYPE&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;LC_COLLATE LC_IDENTIFICATION LC_MEASUREMENT LC_MESSAGES&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;LC_MONETARY LC_NAME LC_NUMERIC LC_PAPER LC_TELEPHONE&quot;</span></span>
<span class="line"><span>Defaults    env_keep += &quot;LC_TIME LC_ALL LANGUAGE LINGUAS _XKB_CHARSET XAUTHORITY&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Defaults    secure_path = /sbin:/bin:/usr/sbin:/usr/bin:/usr/local/bin</span></span></code></pre></div><h4 id="命令部分" tabindex="-1">命令部分 <a class="header-anchor" href="#命令部分" aria-label="Permalink to “命令部分”">​</a></h4><p>命令部分是 <code>sudoers</code> 文件的主體。不使用別名並不會影響你完成要實現的效果，別名只是讓整個配置工作大幅簡化而已。</p><p>這部分使用之前定義的別名來告訴 <code>sudo</code> 哪些人可以在哪些機器上執行哪些操作。一旦你理解了這部分內容的語法，你會發現這些例子都非常的直觀。 下面我們來看看它的語法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ruser           ALL=(ALL) ALL</span></span></code></pre></div><p><em>意即 <code>ruser</code> 可以在任意主機上以任意用户身份運行任意命令</em></p><p>這是一條為用户 <code>ruser</code> 做出的配置。行中第一個 <code>ALL</code> 表示該條規則在所有主機上生效。 第二個 <code>ALL</code> 允許 <code>ruser</code> 以任意其他用户的身份運行命令。 默認情況下， 命令以 <code>root</code> 用户的身份運行， 但 <code>ruser</code> 可以在 <code>sudo</code> 命令列指定程序以其他用户的身份運行。 最後這個 <code>ALL</code> 表示 <code>ruser</code> 可以運行所有命令而不受限制。 這讓 <code>ruser</code> 實際上就變成了 <code>root</code>。</p><p>注意到下面還有一條針對 <code>root</code> 的配置。這允許 <code>root</code> 能通過 <code>sudo</code> 在任何主機上運行任何命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root    ALL=(ALL) ALL</span></span></code></pre></div><p><em>意即 <code>root</code> 可以在任意主機上以任意用户身份運行任意命令</em></p><p>為了實驗一下效果，我註釋掉了這行， 然後以 root 的身份試着直接運行 <code>chown</code>。 出乎意料的是這樣是能成功的。 然後我試了下 <code>sudo chown</code>，結果失敗了，提示信息 “Root is not in the sudoers file。 This incident will be reported”。 也就是説 root 可以直接運行任何命令， 但當加上 <code>sudo</code> 時則不行。 這會阻止 root 像其他用户一樣使用 <code>sudo</code> 命令來運行其他命令， 但是 root 有太多種方法可以繞過這個約束了。</p><p>下面這行是我新增來控制訪問 <code>myprog</code> 的。它指定了只有上面定義的 <code>AUDIO</code> 組中的用户才能在 <code>guest1</code> 這台主機上使用 <code>myprog</code> 這個命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AUDIO   guest1=/usr/local/bin/myprog</span></span></code></pre></div><p><em>允許 AUDIO 組成員在 guest1 主機上訪問 myprog</em></p><p>注意，上面這一行只指定了允許訪問的主機名和程序，而沒有説用户可以以其他用户的身份來運行該程序。</p><h4 id="省略密碼" tabindex="-1">省略密碼 <a class="header-anchor" href="#省略密碼" aria-label="Permalink to “省略密碼”">​</a></h4><p>你也可以通過 <code>NOPASSWORD</code> 來讓 <code>AUDIO</code> 組中的用户無需密碼就能運行 <code>myprog</code>。像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AUDIO   guest1=NOPASSWORD : /usr/local/bin/myprog</span></span></code></pre></div><p><em>允許 AUDIO 組成員在 guest1 主機上不用輸入密碼即可訪問 myprog</em></p><p>我並沒有這樣做，因為我覺得使用 <code>sudo</code> 的用户必須要停下來想清楚他們正在做的事情，這對他們有好處。 我這裏只是舉個例子。</p><h4 id="wheel" tabindex="-1">wheel <a class="header-anchor" href="#wheel" aria-label="Permalink to “wheel”">​</a></h4><p><code>sudoers</code> 文件中命令部分的 <code>wheel</code> 説明（如下所示）允許所有在 <code>wheel</code> 組中的用户在任何機器上運行任何命令。<code>wheel</code> 組在 <code>/etc/group</code> 文件中定義， 用户必須加入該組後才能工作。 組名前面的 <code>%</code> 符號表示 <code>sudo</code> 應該去 <code>/etc/group</code> 文件中查找該組。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>%wheel          ALL = (ALL) ALL</span></span></code></pre></div><p><em>運行所有定義在 /etc/group 文件中的 “wheel” 組成員可以在任意主機上運行全部命令</em></p><p>這種方法很好的實現了為多個用户賦予完全的 root 權限而不用提供 root 密碼。只需要把該用户加入 <code>wheel</code> 組中就能給他們提供完整的 root 的能力。 它也提供了一種通過 <code>sudo</code> 創建的日誌來監控他們行為的途徑。 有些 Linux 發行版， 比如 Ubuntu， 會自動將用户的 ID 加入 <code>/etc/group</code> 中的 <code>wheel</code> 組中， 這使得他們能夠用 <code>sudo</code> 命令運行所有的特權命令。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>我這裏只是小試了一把 <code>sudo</code> — 我只是給一到兩個用户以 root 權限運行單個命令的權限。完成這些只添加了兩行配置（不考慮註釋）。 將某項任務的權限委派給其他非 root 用户非常簡單，而且可以節省你大量的時間。 同時它還會產生日誌來幫你發現問題。</p><p><code>sudoers</code> 文件還有許多其他的配置和能力。查看 <code>sudo</code> 和 <code>sudoers</code> 的 man 手冊可以深入瞭解詳細信息。</p><hr>`,62)),i("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/17/12/using-sudo-delegate"},{default:o(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/17/12/using-sudo-delegate",-1)])]),_:1})]),i("p",null,[s[5]||(s[5]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/dboth"},{default:o(()=>[...s[2]||(s[2]=[e("David Both",-1)])]),_:1}),s[6]||(s[6]=e(" 譯者：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[7]||(s[7]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:o(()=>[...s[9]||(s[9]=[e("Linux中國",-1)])]),_:1}),s[12]||(s[12]=e(" 榮譽推出",-1))])])}const C=p(r,[["render",u]]);export{A as __pageData,C as default};
